import { StockRecord, MarketCapCategory, NSEIndexKey, IndexOption } from "../types";

export interface RawStockItem {
  id: string;
  symbol: string;
  ticker: string;
  name: string;
  sector: string;
  category: MarketCapCategory;
  isNifty50?: boolean;
  isNiftyNext50?: boolean;
  isNiftyMidcap150?: boolean;
  isNiftySmallcap250?: boolean;
  lastClose: number;
  cmp: number;
  cmpChangePct: number;
  high52w: number;
  low52w: number;
  return1M: number;
  return3M: number;
  return1Y: number;
  previousReturn1M?: number;
  previousReturn3M?: number;
}

